// Parser implementation
pub fn parse_database(input: &str) -> Result<Database, Box<dyn std::error::Error>> {
    let pairs = JPortalParser::parse(Rule::database, input)?;
    
    for pair in pairs {
        match pair.as_rule() {
            Rule::database => {
                return parse_database_rule(pair);
            }
            _ => unreachable!(),
        }
    }
    
    Err("No database found".into())
}

fn parse_database_rule(pair: pest::iterators::Pair<Rule>) -> Result<Database, Box<dyn std::error::Error>> {
    let mut database = Database {
        name: String::new(),
        userid: String::new(),
        password: String::new(),
        flags: Vec::new(),
        package_name: None,
        output: None,
        imports: Vec::new(),
        server: String::new(),
        schema: None,
        tables: Vec::new(),
        views: Vec::new(),
    };
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::database_name => {
                for name_pair in inner_pair.into_inner() {
                    database.name = parse_ident_or_string_from_pair(name_pair);
                }
            }
            Rule::flags_section => {
                for flag_pair in inner_pair.into_inner() {
                    if let Rule::string_literal = flag_pair.as_rule() {
                        database.flags.push(parse_string_literal(flag_pair.as_str()));
                    }
                }
            }
            Rule::package_section => {
                for pkg_pair in inner_pair.into_inner() {
                    if let Rule::package_ident = pkg_pair.as_rule() {
                        database.package_name = Some(pkg_pair.as_str().to_string());
                    }
                }
            }
            Rule::output_section => {
                for out_pair in inner_pair.into_inner() {
                    if let Rule::ident_or_string = out_pair.as_rule() {
                        database.output = Some(parse_ident_or_string(out_pair));
                    }
                }
            }
            Rule::import_section => {
                for imp_pair in inner_pair.into_inner() {
                    if let Rule::ident_or_string = imp_pair.as_rule() {
                        database.imports.push(parse_ident_or_string(imp_pair));
                    }
                }
            }
            Rule::connect_section => {
                parse_connect_section(inner_pair, &mut database)?;
            }
            Rule::tables_section => {
                parse_tables_section(inner_pair, &mut database)?;
            }
            _ => {}
        }
    }
    
    Ok(database)
}

// Enhanced string parsing - matches JavaCC jString() and fixString()
fn parse_jstring(input: &str) -> String {
    // Enhanced string literal parsing with fixString() behavior
    let trimmed = input.trim_matches('"').trim_matches('\'');
    
    // Process escape sequences like JavaCC fixString()
    let mut result = String::new();
    let mut chars = trimmed.chars().peekable();
    
    while let Some(ch) = chars.next() {
        if ch == '\\' {
            if let Some(&next_ch) = chars.peek() {
                match next_ch {
                    'n' => {
                        result.push('\n');
                        chars.next();
                    }
                    't' => {
                        result.push('\t');
                        chars.next();
                    }
                    'r' => {
                        result.push('\r');
                        chars.next();
                    }
                    '\\' => {
                        result.push('\\');
                        chars.next();
                    }
                    '"' => {
                        result.push('"');
                        chars.next();
                    }
                    '\'' => {
                        result.push('\'');
                        chars.next();
                    }
                    _ => {
                        // For any other character after \, just include both characters
                        result.push(ch);
                        result.push(chars.next().unwrap());
                    }
                }
            } else {
                result.push(ch);
            }
        } else {
            result.push(ch);
        }
    }
    
    result
}

// Enhanced identifier parsing - matches JavaCC jIdent() behavior
fn parse_ident_or_string_from_pair(pair: pest::iterators::Pair<Rule>) -> String {
    match pair.as_rule() {
        Rule::identifier => pair.as_str().to_string(),
        Rule::literal_identifier => {
            // Handle L'identifier' format - extract content between quotes
            let s = pair.as_str();
            if s.len() > 3 && (s.starts_with("L'") || s.starts_with("l'")) && s.ends_with('\'') {
                s[2..s.len()-1].to_string()
            } else {
                s.to_string()
            }
        }
        Rule::string_literal => pair.as_str().to_string(), // Keep quotes for consistency
        _ => pair.as_str().to_string(),
    }
}

fn parse_ident_or_string(pair: pest::iterators::Pair<Rule>) -> String {
    for inner_pair in pair.clone().into_inner() {
        return parse_ident_or_string_from_pair(inner_pair);
    }
    pair.as_str().to_string()
}

fn parse_connect_section(pair: pest::iterators::Pair<Rule>, database: &mut Database) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::server_clause => {
                for server_pair in inner_pair.into_inner() {
                    if let Rule::ident_or_string = server_pair.as_rule() {
                        database.server = parse_ident_or_string(server_pair);
                    }
                }
            }
            Rule::schema_clause => {
                for schema_pair in inner_pair.into_inner() {
                    if let Rule::ident_or_string = schema_pair.as_rule() {
                        database.schema = Some(parse_ident_or_string(schema_pair));
                    }
                }
            }
            Rule::userid_clause => {
                for userid_pair in inner_pair.into_inner() {
                    if let Rule::identifier = userid_pair.as_rule() {
                        database.userid = userid_pair.as_str().to_string();
                    }
                }
            }
            Rule::password_clause => {
                for password_pair in inner_pair.into_inner() {
                    if let Rule::identifier = password_pair.as_rule() {
                        database.password = password_pair.as_str().to_string();
                    }
                }
            }
            _ => {}
        }
    }
    Ok(())
}

// Enhanced tables parsing - matches JavaCC jTables() behavior
fn parse_tables_section(pair: pest::iterators::Pair<Rule>, database: &mut Database) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::table_definition => {
                let table = parse_table_definition(inner_pair)?;
                database.tables.push(table);
            }
            _ => {}
        }
    }
    Ok(())
}

fn parse_table_definition(pair: pest::iterators::Pair<Rule>) -> Result<Table, Box<dyn std::error::Error>> {
    let mut table = Table {
        name: String::new(),
        alias: None,
        check: None,
        comments: Vec::new(),
        options: Vec::new(),
        fields: Vec::new(),
        keys: Vec::new(),
        links: Vec::new(),
        grants: Vec::new(),
        views: Vec::new(),
        consts: Vec::new(),
        procs: Vec::new(),
        parameters: Vec::new(),
        is_import: false,
        import_fields: Vec::new(),
        is_literal: false,
        literal_name: String::new(),
        start_line: None,
        has_execute: false,
        has_select: false,
        has_delete: false,
        has_insert: false,
        has_update: false,
        has_primary_key: false,
        has_sequence: false,
        has_sequence_returning: false,
        has_identity: false,
        has_std_procs: false,
        has_big_xml: false,
        has_big_json: false,
    };
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::table_section => {
                parse_table_section_into(inner_pair, &mut table)?;
            }
            Rule::table_import_section => {
                parse_table_import_section_into(inner_pair, &mut table)?;
                table.is_import = true;
            }
            Rule::const_section => {
                let const_item = parse_const_section(inner_pair)?;
                table.consts.push(const_item);
            }
            Rule::enhanced_grant_section => {
                let grant = parse_enhanced_grant_section(inner_pair, &mut table)?;
                table.grants.push(grant);
            }
            Rule::original_grant_section => {
                let grant = parse_original_grant_section(inner_pair)?;
                table.grants.push(grant);
            }
            Rule::enhanced_key_section => {
                let key = parse_enhanced_key_section(inner_pair, &mut table)?;
                table.keys.push(key);
            }
            Rule::original_key_section => {
                let key = parse_original_key_section(inner_pair)?;
                table.keys.push(key);
            }
            Rule::enhanced_link_section => {
                let link = parse_enhanced_link_section(inner_pair, &mut table)?;
                table.links.push(link);
            }
            Rule::original_link_section => {
                let link = parse_original_link_section(inner_pair)?;
                table.links.push(link);
            }
            Rule::enhanced_view_section => {
                let view = parse_enhanced_view_section(inner_pair)?;
                table.views.push(view);
            }
            Rule::proc_section => {
                let proc = parse_proc_section(inner_pair)?;
                table.procs.push(proc);
            }
            Rule::parm_section => {
                let parameter = parse_parm_section(inner_pair)?;
                table.parameters.push(parameter);
            }
            _ => {}
        }
    }
    
    Ok(table)
}

fn parse_table_section_into(pair: pest::iterators::Pair<Rule>, table: &mut Table) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::identifier => {
                table.name = inner_pair.as_str().to_string();
            }
            Rule::alias_clause => {
                table.alias = Some(parse_alias_clause(inner_pair)?);
            }
            Rule::check_clause => {
                table.check = Some(parse_check_clause(inner_pair)?);
            }
            Rule::comment_clause => {
                table.comments.push(parse_comment_clause(inner_pair)?);
            }
            Rule::options_clause => {
                table.options = parse_options_clause(inner_pair)?;
            }
            Rule::field_def => {
                let field = parse_field_def(inner_pair)?;
                table.fields.push(field);
            }
            Rule::package_field_def => {
                let field = parse_package_field_def(inner_pair)?;
                table.fields.push(field);
            }
            _ => {}
        }
    }
    Ok(())
}

fn parse_table_import_section_into(pair: pest::iterators::Pair<Rule>, table: &mut Table) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::ident_or_string => {
                table.name = parse_ident_or_string(inner_pair);
            }
            Rule::field_import_list => {
                table.import_fields = parse_field_import_list(inner_pair)?;
            }
            Rule::alias_clause => {
                table.alias = Some(parse_alias_clause(inner_pair)?);
            }
            _ => {}
        }
    }
    Ok(())
}

fn parse_alias_clause(pair: pest::iterators::Pair<Rule>) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::ident_or_string = inner_pair.as_rule() {
            return Ok(parse_ident_or_string(inner_pair));
        }
    }
    Ok(String::new())
}

fn parse_check_clause(pair: pest::iterators::Pair<Rule>) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::string_literal = inner_pair.as_rule() {
            return Ok(parse_string_literal(inner_pair.as_str()));
        }
    }
    Ok(String::new())
}

fn parse_comment_clause(pair: pest::iterators::Pair<Rule>) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.clone().into_inner() {
        if let Rule::string_literal = inner_pair.as_rule() {
            return Ok(parse_string_literal(inner_pair.as_str()));
        }
    }
    Ok(pair.as_str().to_string())
}

fn parse_options_clause(pair: pest::iterators::Pair<Rule>) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut options = Vec::new();
    for inner_pair in pair.into_inner() {
        if let Rule::string_literal = inner_pair.as_rule() {
            options.push(parse_string_literal(inner_pair.as_str()));
        }
    }
    Ok(options)
}

fn parse_field_import_list(pair: pest::iterators::Pair<Rule>) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut fields = Vec::new();
    for inner_pair in pair.into_inner() {
        if let Rule::identifier = inner_pair.as_rule() {
            fields.push(inner_pair.as_str().to_string());
        }
    }
    Ok(fields)
}

fn parse_package_field_def(pair: pest::iterators::Pair<Rule>) -> Result<Field, Box<dyn std::error::Error>> {
    let mut field = Field {
        name: String::new(),
        alias: None,
        field_type: FieldType::Int,
        length: None,
        precision: None,
        scale: None,
        is_null: true, // fieldsNullByDefault in JavaCC
        is_calc: false,
        default_value: None,
        check_value: None,
        comments: Vec::new(),
        enums: Vec::new(),
        value_list: Vec::new(),
        is_literal: false,
        literal_name: String::new(),
        is_package_field: true,
        is_sequence: false,
        enum_type: None,
        lookup_name: None,
        enum_link: None,
        is_primary: false,
        is_out: false,
        is_in: false,
    };
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::package_ident => {
                field.name = inner_pair.as_str().to_string();
                // TODO: Set is_literal and literal_name based on parsing
            }
            Rule::alias_clause => {
                field.alias = Some(parse_alias_clause(inner_pair)?);
            }
            Rule::field_type => {
                parse_field_type_into(inner_pair, &mut field)?;
            }
            Rule::package_field_modifiers => {
                parse_package_field_modifiers(inner_pair, &mut field)?;
            }
            Rule::comment_clause => {
                field.comments.push(parse_comment_clause(inner_pair)?);
            }
            _ => {}
        }
    }
    
    Ok(field)
}

fn parse_package_field_modifiers(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    let mut not_modifier = false;
    let mut expecting_default_value = false;
    let mut expecting_check_value = false;
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::DEFAULT => {
                expecting_default_value = true;
            }
            Rule::string_literal => {
                if expecting_default_value {
                    field.default_value = Some(parse_string_literal(inner_pair.as_str()));
                    expecting_default_value = false;
                } else if expecting_check_value {
                    field.check_value = Some(parse_string_literal(inner_pair.as_str()));
                    expecting_check_value = false;
                }
            }
            Rule::NOT => {
                not_modifier = true;
            }
            Rule::NULL => {
                field.is_null = !not_modifier;
                not_modifier = false;
            }
            Rule::CALC => {
                field.is_calc = true;
            }
            Rule::CHECK => {
                expecting_check_value = true;
            }
            _ => {}
        }
    }
    Ok(())
}

fn parse_field_def(pair: pest::iterators::Pair<Rule>) -> Result<Field, Box<dyn std::error::Error>> {
    let mut field = Field {
        name: String::new(),
        alias: None,
        field_type: FieldType::Int,
        length: None,
        precision: None,
        scale: None,
        is_null: true,
        is_calc: false,
        default_value: None,
        check_value: None,
        comments: Vec::new(),
        enums: Vec::new(),
        value_list: Vec::new(),
        is_literal: false,
        literal_name: String::new(),
        is_package_field: false,
        is_sequence: false,
        enum_type: None,
        lookup_name: None,
        enum_link: None,
        is_primary: false,
        is_out: false,
        is_in: false,
    };
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::identifier => {
                field.name = inner_pair.as_str().to_string();
            }
            Rule::paren_alias_clause => {
                field.alias = Some(parse_paren_alias_clause(inner_pair)?);
            }
            Rule::field_type => {
                parse_field_type_into(inner_pair, &mut field)?;
            }
            Rule::field_modifiers => {
                parse_field_modifiers(inner_pair, &mut field)?;
            }
            Rule::lookup_type => {
                field.field_type = FieldType::Lookup;
                parse_lookup_type_into(inner_pair, &mut field)?;
            }
            Rule::comment_clause => {
                field.comments.push(parse_comment_clause(inner_pair)?);
            }
            _ => {}
        }
    }
    
    Ok(field)
}

fn parse_paren_alias_clause(pair: pest::iterators::Pair<Rule>) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::identifier = inner_pair.as_rule() {
            return Ok(inner_pair.as_str().to_string());
        }
    }
    Ok(String::new())
}

fn parse_field_type_into(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::BLOB => {
                field.field_type = FieldType::Blob;
                field.length = Some(0);
            }
            Rule::BOOLEAN => {
                field.field_type = FieldType::Boolean;
                field.length = Some(1);
            }
            Rule::BYTE => {
                field.field_type = FieldType::Byte;
                field.length = Some(1);
            }
            Rule::CHAR => {
                field.field_type = FieldType::Char;
                field.length = Some(1);
            }
            Rule::ANSICHAR => {
                field.field_type = FieldType::AnsiChar;
                field.length = Some(1);
            }
            Rule::WCHAR => {
                field.field_type = FieldType::WChar;
                field.length = Some(1);
            }
            Rule::WANSICHAR => {
                field.field_type = FieldType::WAnsiChar;
                field.length = Some(1);
            }
            Rule::UTF8 => {
                field.field_type = FieldType::Utf8;
                field.length = Some(1);
            }
            Rule::SHORT => {
                field.field_type = FieldType::Short;
                field.length = Some(2);
            }
            Rule::INT => {
                field.field_type = FieldType::Int;
                field.length = Some(4);
            }
            Rule::LONG => {
                field.field_type = FieldType::Long;
                field.length = Some(8);
            }
            Rule::UID => {
                field.field_type = FieldType::Uid;
                field.length = Some(16);
            }
            Rule::DATE => {
                field.field_type = FieldType::Date;
                field.length = Some(8);
            }
            Rule::DATETIME => {
                field.field_type = FieldType::DateTime;
                field.length = Some(14);
            }
            Rule::TIME => {
                field.field_type = FieldType::Time;
                field.length = Some(6);
            }
            Rule::TIMESTAMP => {
                field.field_type = FieldType::Timestamp;
                field.length = Some(14);
            }
            Rule::AUTOTIMESTAMP => {
                field.field_type = FieldType::AutoTimestamp;
                field.length = Some(14);
            }
            Rule::TLOB => {
                field.field_type = FieldType::Tlob;
                field.length = Some(0);
            }
            Rule::XML => {
                field.field_type = FieldType::Xml;
                field.length = Some(1000); // DEFAULT_XML
            }
            Rule::BIGXML => {
                field.field_type = FieldType::BigXml;
                field.length = Some(10000); // DEFAULT_BIG_XML
            }
            Rule::JSON => {
                field.field_type = FieldType::Json;
                field.length = Some(1000); // DEFAULT_JSON
            }
            Rule::BIGJSON => {
                field.field_type = FieldType::BigJson;
                field.length = Some(10000); // DEFAULT_BIG_JSON
            }
            Rule::USERSTAMP => {
                field.field_type = FieldType::UserStamp;
                field.length = Some(50);
            }
            Rule::SEQUENCE => {
                field.field_type = FieldType::Sequence;
                field.is_sequence = true;
                field.length = Some(4);
            }
            Rule::BIGSEQUENCE => {
                field.field_type = FieldType::BigSequence;
                field.is_sequence = true;
                field.length = Some(8);
            }
            Rule::IDENTITY => {
                field.field_type = FieldType::Identity;
                field.is_sequence = true;
                field.length = Some(4);
            }
            Rule::BIGIDENTITY => {
                field.field_type = FieldType::BigIdentity;
                field.is_sequence = true;
                field.length = Some(8);
            }
            Rule::DOUBLE => {
                field.field_type = FieldType::Double;
                field.length = Some(8);
            }
            Rule::FLOAT => {
                field.field_type = FieldType::Float;
                field.length = Some(8);
            }
            Rule::MONEY => {
                field.field_type = FieldType::Money;
                field.length = Some(8);
            }
            Rule::enhanced_char_size => {
                parse_enhanced_char_size_into(inner_pair, field)?;
            }
            Rule::enhanced_float_size => {
                parse_enhanced_float_size_into(inner_pair, field)?;
            }
            Rule::float_size => {
                parse_float_size_into(inner_pair, field)?;
            }
            Rule::enhanced_enum_value => {
                parse_enhanced_enum_value_into(inner_pair, field)?;
            }
            Rule::enhanced_char_list => {
                parse_enhanced_char_list_into(inner_pair, field)?;
            }
            Rule::enhanced_enum_char => {
                parse_enhanced_enum_char_into(inner_pair, field)?;
            }
            Rule::char_list => {
                parse_char_list_into(inner_pair, field)?;
            }
            Rule::enum_value => {
                parse_enum_value_into(inner_pair, field)?;
            }
            _ => {}
        }
    }
    Ok(())
}

// Enhanced char size parsing - matches jCharsize()
fn parse_enhanced_char_size_into(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::number = inner_pair.as_rule() {
            if let Ok(size) = inner_pair.as_str().parse::<i32>() {
                field.length = Some(size);
            }
        }
    }
    Ok(())
}

// Enhanced float size parsing - matches jFloatsize()
fn parse_enhanced_float_size_into(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    let mut numbers = Vec::new();
    for inner_pair in pair.into_inner() {
        if let Rule::number = inner_pair.as_rule() {
            if let Ok(num) = inner_pair.as_str().parse::<i32>() {
                numbers.push(num);
            }
        }
    }
    
    if numbers.len() >= 2 {
        field.precision = Some(numbers[0]);
        field.scale = Some(numbers[1]);
    }
    Ok(())
}

// Original float size parsing for backward compatibility
fn parse_float_size_into(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    let mut numbers = Vec::new();
    for inner_pair in pair.into_inner() {
        if let Rule::number = inner_pair.as_rule() {
            if let Ok(num) = inner_pair.as_str().parse::<i32>() {
                numbers.push(num);
            }
        }
    }
    
    if !numbers.is_empty() {
        field.precision = Some(numbers[0]);
        if numbers.len() > 1 {
            field.scale = Some(numbers[1]);
        }
    }
    Ok(())
}

// Enhanced enum value parsing - matches jEnumValue()
fn parse_enhanced_enum_value_into(pair: pest::iterators::Pair<Rule>, field: &mut Field) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::LINK => {
                // Skip LINK keyword, next should be identifier
            }
            Rule::identifier => {
                if field.enum_link.is_none() {
                    field.enum_link = Some(inner_pair.as_str().to_string());
                }
            }
            Rule::enum_item => {
                let enum_item = parse_enum_item(inner_pair)?;
                field.enums.push(enum_item);
            }
            _ => {}
        }
    }
    Ok(())
}

