// Enhanced grant section parsing - matches jGrant() and jPermission()
fn parse_enhanced_grant_section(pair: pest::iterators::Pair<Rule>, table: &mut Table) -> Result<Grant, Box<dyn std::error::Error>> {
    let mut grant = Grant {
        perms: Vec::new(),
        users: Vec::new(),
    };
    
    let mut parsing_users = false;
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::permission => {
                if !parsing_users {
                    let perm = parse_permission(inner_pair, table)?;
                    grant.perms.push(perm);
                }
            }
            Rule::TO => {
                parsing_users = true;
            }
            Rule::non_keyword_identifier => {
                if parsing_users {
                    grant.users.push(inner_pair.as_str().to_string());
                }
            }
            _ => {}
        }
    }
    
    Ok(grant)
}

// Enhanced permission parsing - matches JavaCC jPermission() behavior
fn parse_permission(pair: pest::iterators::Pair<Rule>, table: &mut Table) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::ALL => {
                // Set all permission flags like JavaCC
                table.has_execute = true;
                table.has_select = true;
                table.has_delete = true;
                table.has_insert = true;
                table.has_update = true;
                return Ok("all".to_string());
            }
            Rule::DELETE => {
                table.has_delete = true;
                return Ok("delete".to_string());
            }
            Rule::INSERT => {
                table.has_insert = true;
                return Ok("insert".to_string());
            }
            Rule::SELECT => {
                table.has_select = true;
                return Ok("select".to_string());
            }
            Rule::UPDATE => {
                table.has_update = true;
                return Ok("update".to_string());
            }
            Rule::EXECUTE => {
                table.has_execute = true;
                return Ok("execute".to_string());
            }
            _ => {}
        }
    }
    Ok("unknown".to_string())
}

// Enhanced link section parsing - matches jLink() and jLinkColumn()
fn parse_enhanced_link_section(pair: pest::iterators::Pair<Rule>, table: &mut Table) -> Result<Link, Box<dyn std::error::Error>> {
    let mut link = Link {
        name: String::new(),
        fields: Vec::new(),
        link_fields: Vec::new(),
        is_delete_cascade: false,
        is_update_cascade: false,
        options: Vec::new(),
    };
    
    let mut all_identifiers = Vec::new();
    let mut seen_cascade_or_options = false;
    let mut parsing_link_fields = false;
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::package_ident => {
                link.name = inner_pair.as_str().trim().to_string();
            }
            Rule::LEFTPAREN => {
                parsing_link_fields = true;
            }
            Rule::RIGHTPAREN => {
                parsing_link_fields = false;
            }
            Rule::non_keyword_identifier => {
                let field_name = inner_pair.as_str().to_string();
                
                if parsing_link_fields {
                    // This is a link field (in parentheses)
                    link.link_fields.push(field_name);
                } else {
                    // This is a regular field - apply jLinkColumn() validation
                    if !table.has_field(&field_name) {
                        eprintln!("Warning: {} field {} not present in table", link.name, field_name);
                    } else if link.has_field(&field_name) {
                        eprintln!("Warning: {} field {} already present in link", link.name, field_name);
                    } else {
                        link.fields.push(field_name);
                    }
                }
                all_identifiers.push(inner_pair.as_str().to_string());
            }
            Rule::DELETE => {
                link.is_delete_cascade = true;
                seen_cascade_or_options = true;
            }
            Rule::UPDATE => {
                link.is_update_cascade = true;
                seen_cascade_or_options = true;
            }
            Rule::CASCADE => {
                // CASCADE is handled by the DELETE/UPDATE rules
            }
            Rule::OPTIONS => {
                seen_cascade_or_options = true;
            }
            Rule::string_literal => {
                link.options.push(parse_string_literal(inner_pair.as_str()));
            }
            _ => {}
        }
    }
    
    // If we didn't parse fields through the validation logic above,
    // fall back to the original logic for backward compatibility
    if link.fields.is_empty() && !all_identifiers.is_empty() {
        if seen_cascade_or_options && all_identifiers.len() > 1 {
            let last_idx = all_identifiers.len() - 1;
            if link.link_fields.is_empty() {
                link.link_fields = all_identifiers[0..last_idx].to_vec();
            }
            link.fields = vec![all_identifiers[last_idx].clone()];
        } else {
            link.fields = all_identifiers;
        }
    }
    
    Ok(link)
}

// Enhanced view section parsing - matches jView(), jViewAlias(), jNewViewCode(), and jOldViewCode()
fn parse_enhanced_view_section(pair: pest::iterators::Pair<Rule>) -> Result<View, Box<dyn std::error::Error>> {
    let mut view = View {
        name: String::new(),
        users: Vec::new(),
        aliases: Vec::new(),
        lines: Vec::new(),
        start_line: None,
    };
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::identifier => {
                view.name = inner_pair.as_str().to_string();
                // Set start line if available (matches JavaCC view.start = t.beginLine)
                view.start_line = Some(1); // In a real implementation, you'd get this from the parser
            }
            Rule::TO => {
                // Skip TO keyword, next should be users
            }
            Rule::non_keyword_identifier => {
                let user_name = inner_pair.as_str().to_string();
                
                // Validation logic from JavaCC jView() -> jUser()
                if view.has_user(&user_name) {
                    eprintln!("Warning: {} user {} already present in view", view.name, user_name);
                } else {
                    view.users.push(user_name);
                }
            }
            Rule::OUTPUT => {
                // Skip OUTPUT keyword, next should be aliases
            }
            Rule::view_alias => {
                let _alias = parse_view_alias_with_validation(inner_pair, &mut view)?;
                // Alias is added in the validation function if valid
            }
            Rule::view_code => {
                parse_view_code_into(inner_pair, &mut view)?;
            }
            Rule::old_view_code => {
                parse_old_view_code_into(inner_pair, &mut view)?;
            }
            _ => {}
        }
    }
    
    Ok(view)
}

// Enhanced view alias parsing - matches JavaCC jViewAlias()
fn parse_view_alias_with_validation(pair: pest::iterators::Pair<Rule>, view: &mut View) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::identifier = inner_pair.as_rule() {
            let alias_name = inner_pair.as_str().to_string();
            
            // Validation logic from JavaCC jViewAlias()
            if view.has_alias(&alias_name) {
                eprintln!("Warning: {} alias {} already present in view", view.name, alias_name);
            } else {
                view.aliases.push(alias_name.clone());
            }
            
            return Ok(alias_name);
        }
    }
    Ok(String::new())
}

// Enhanced view code parsing - matches JavaCC jNewViewCode()
fn parse_view_code_into(pair: pest::iterators::Pair<Rule>, view: &mut View) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::codeline = inner_pair.as_rule() {
            let line = parse_codeline_enhanced(inner_pair)?;
            view.lines.push(line);
        }
    }
    Ok(())
}

// Enhanced old view code parsing - matches JavaCC jOldViewCode()
fn parse_old_view_code_into(pair: pest::iterators::Pair<Rule>, view: &mut View) -> Result<(), Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::raw_content = inner_pair.as_rule() {
            // Process raw content like JavaCC jOldViewCode() - split by lines and trim
            let content = inner_pair.as_str();
            for line in content.lines() {
                let trimmed_line = line.trim();
                if !trimmed_line.is_empty() {
                    view.lines.push(trimmed_line.to_string());
                }
            }
        }
    }
    Ok(())
}

// Enhanced codeline parsing - matches JavaCC jNewViewCode() CODELINE processing
fn parse_codeline_enhanced(pair: pest::iterators::Pair<Rule>) -> Result<String, Box<dyn std::error::Error>> {
    for inner_pair in pair.into_inner() {
        if let Rule::string_literal = inner_pair.as_rule() {
            // Process like JavaCC: line = t.image.trim() with jString() processing
            let line = parse_jstring(inner_pair.as_str()).trim().to_string();
            return Ok(line);
        }
    }
    Ok(String::new())
}

fn parse_field_list(pair: pest::iterators::Pair<Rule>) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut fields = Vec::new();
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::identifier => {
                fields.push(inner_pair.as_str().to_string());
            }
            _ => {}
        }
    }
    
    Ok(fields)
}

fn parse_proc_section(pair: pest::iterators::Pair<Rule>) -> Result<Proc, Box<dyn std::error::Error>> {
    let mut proc = Proc {
        name: String::new(),
        is_proc: false,
        is_sproc: false,
        is_built_in: false,
        is_update: false,
        is_single: false,
        is_std: false,
        has_returning: false,
        use_std: false,
        extends_std: false,
        comments: Vec::new(),
        options: Vec::new(),
        inputs: Vec::new(),
        outputs: Vec::new(),
        lines: Vec::new(),
        fields: Vec::new(),
        start_line: Some(1), // Set start line (in real implementation, get from parser position)
        table: None,
        row_count: None,
        // Additional fields for jNewProc functionality
        is_multiple_input: false,
        no_rows: None,
        has_updates: false,
        is_sql: false,
        dynamics: Vec::new(),
        dynamic_sizes: Vec::new(),
        // Additional fields for data and IDL blocks
        is_data: false,
        is_idl_code: false,
        update_fields: Vec::new(),
        order_fields: Vec::new(),
        dynamic_strung: Vec::new(),
    };
    
    let mut in_data_block = false;
    let mut in_idl_block = false;
    
    for inner_pair in pair.into_inner() {
        match inner_pair.as_rule() {
            Rule::PROC => {
                proc.is_proc = true;
            }
            Rule::SPROC => {
                proc.is_sproc = true;
            }
            Rule::SQLDATA => {
                proc.is_data = true;
                in_data_block = true;
            }
            Rule::IDLCODE => {
                proc.is_idl_code = true;
                in_idl_block = true;
            }
            Rule::ENDDATA => {
                // Removed - no longer supporting old DATA/ENDDATA blocks
            }
            Rule::data_line => {
                if in_data_block {
                    let line = inner_pair.as_str().trim().to_string();
                    proc.lines.push(line);
                }
            }
            Rule::idl_line => {
                if in_idl_block {
                    let line = inner_pair.as_str().trim().to_string();
                    if !line.is_empty() {
                        proc.lines.push(line);
                    }
                }
            }
            Rule::identifier => {
                if proc.name.is_empty() && !in_data_block && !in_idl_block {
                    proc.name = inner_pair.as_str().to_string();
                }
            }
            Rule::INSERT => {
                proc.name = "Insert".to_string();
                proc.is_built_in = true;
            }
            Rule::RETURNING => {
                proc.has_returning = true;
            }
            Rule::UPDATE => {
                if proc.name.is_empty() {
                    proc.name = "Update".to_string();
                    proc.is_built_in = true;
                    proc.is_update = true;
                }
            }
            Rule::UPDATEFOR => {
                proc.name = "UpdateFor".to_string();
                proc.is_built_in = true;
                proc.is_update = true;
            }
            Rule::UPDATEBY => {
                proc.name = "UpdateBy".to_string();
                proc.is_built_in = true;
                proc.is_update = true;
            }
            Rule::BULKINSERT => {
                proc.name = "BulkInsert".to_string();
                proc.is_built_in = true;
            }
            Rule::MAXTMSTAMP => {
                proc.name = "MaxTmStamp".to_string();
                proc.is_built_in = true;
            }
            Rule::BULKUPDATE => {
                proc.name = "BulkUpdate".to_string();
                proc.is_built_in = true;
                proc.is_update = true;
            }
            Rule::DELETEONE => {
                proc.name = "DeleteOne".to_string();
                proc.is_built_in = true;
            }
            Rule::DELETEALL => {
                proc.name = "DeleteAll".to_string();
                proc.is_built_in = true;
            }
            Rule::DELETEBY => {
                proc.name = "DeleteBy".to_string();
                proc.is_built_in = true;
            }
            Rule::SELECTONE => {
                proc.name = "SelectOne".to_string();
                proc.is_built_in = true;
                proc.is_single = true;
            }
            Rule::SELECTONEBY => {
                proc.name = "SelectOneBy".to_string();
                proc.is_built_in = true;
                proc.is_single = true;
            }
            Rule::SELECTBY => {
                proc.name = "SelectBy".to_string();
                proc.is_built_in = true;
            }
            Rule::SELECTALL => {
                proc.name = "SelectAll".to_string();
                proc.is_built_in = true;
            }
            Rule::COUNT => {
                proc.name = "Count".to_string();
                proc.is_built_in = true;
            }
            Rule::EXISTS => {
                proc.name = "Exists".to_string();
                proc.is_built_in = true;
            }
            Rule::MERGE => {
                proc.name = "Merge".to_string();
                proc.is_built_in = true;
            }
            Rule::STANDARD => {
                proc.is_std = true;
            }
            Rule::AS => {
                // Handle AS clause for custom names
            }
            Rule::custom_select_proc => {
                parse_custom_select_proc_into(inner_pair, &mut proc)?;
            }
            Rule::user_proc => {
                parse_user_proc_into(inner_pair, &mut proc)?;
            }
            Rule::proc_column => {
                let field_name = parse_proc_column(inner_pair)?;
                proc.fields.push(field_name);
            }
            Rule::row_count => {
                proc.row_count = parse_row_count(inner_pair)?;
            }
            Rule::OPTIONS => {
                // Skip the keyword, options will be parsed separately
            }
            Rule::string_literal => {
                // This could be an option value or data content
                if in_data_block || in_idl_block {
                    let line = parse_string_literal(inner_pair.as_str());
                    proc.lines.push(line);
                } else {
                    let line = parse_string_literal(inner_pair.as_str());
                    println!("Processing string_literal: '{}'", line);
                    println!("  in_data_block: {}, in_idl_block: {}", in_data_block, in_idl_block);
                    println!("  proc.name: '{}', proc.is_built_in: {}, proc.extends_std: {}", proc.name, proc.is_built_in, proc.extends_std);
                    println!("  line.contains('&'): {}", line.contains('&'));
                    
                    // Check if this is SQL code with dynamic variables
                    if line.contains('&') && (proc.extends_std || !proc.is_built_in) {
                        println!("  -> Processing as dynamic SQL");
                        let processed_line = parse_dynamics(&line, &mut proc)?;
                        proc.lines.push(processed_line);
                    } else if proc.name.is_empty() || proc.is_built_in {
                        println!("  -> Adding as option");
                        // This is likely an option value
                        proc.options.push(line);
                    } else {
                        println!("  -> Adding as regular SQL line");
                        // This is likely SQL code without dynamic variables
                        proc.lines.push(line);
                    }
                }
            }
            Rule::field_def => {
                let field = parse_field_def(inner_pair)?;
                proc.outputs.push(field);
            }
            _ => {
                // Handle other rules as needed
            }
        }
    }
    
    Ok(proc)
}

